import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // General rule: the contract accepts calls to sendTo made by the deployer (owner).
    // Fuzzed parameter: address receiver (must be a valid address distinct from zero)
    function testFuzz_property(address receiver, uint256 amount) public {
        // keep receiver in a wide admissible domain
        vm.assume(receiver != address(0));
        // The deployer at setUp() is the owner. We simulate the owner calling sendTo.
        // Ensure owner has enough balance to send `amount` with transfer semantics.
        address owner = address(this); // when setUp deployed c, msg.sender was this test contract
        // Fund the contract so it can transfer out `amount` (transfer uses contract balance)
        // We will fund c with a large ether amount so any fuzzed amount up to its balance can be sent.
        uint256 fund = 1 ether;
        vm.deal(address(c), fund);

        // bound amount to a reasonable range so transfer does not OOG; keep wide by allowing 0..fund
        uint256 sendAmount = amount % (fund + 1);

        // Call sendTo as owner (the test contract is the owner). We must detect whether the call succeeds.
        bool ok;
        try c.sendTo(receiver, sendAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the universal property: for ALL admissible inputs, the reference implementation (correct C)
        // accepts calls from the owner (i.e., the owner-facing require passes). The mutant inverts the check,
        // so for owner calls the mutant will reject and this assertion will fail under the mutant for some inputs.
        assertTrue(ok);
    }
}

