pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: receiver address and amount
    function testFuzz_property(address receiver, uint256 amount) public {
        // keep receiver non-zero and amount within contract funding bounds
        vm.assume(receiver != address(0));
        // bound amount to a reasonable max so vm.deal and transfer work in tests
        amount = bound(amount, 0, 1 ether);

        // fund the contract with the amount so it can transfer
        vm.deal(address(c), amount);

        // the constructor set msg.sender as owner when c was deployed in setUp()
        // owner is address(this) at deployment; however in setUp() c was created by this test
        // contract, so owner == address(this). We will act as that owner to call sendTo.

        // record balances before
        uint256 beforeContract = address(c).balance;
        uint256 beforeReceiver = receiver.balance;
        uint256 beforeOwner = address(this).balance;

        bool ok;
        // call sendTo as owner (this test contract)
        try c.sendTo(payable(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful call (ok == true), the reference implementation will have
        // transferred `amount` from the contract to `receiver`. Therefore:
        // - address(c).balance == beforeContract - amount
        // - receiver.balance == beforeReceiver + amount
        // If the mutant sends to msg.sender instead, then when owner != receiver the receiver's
        // balance will not increase. This test asserts the general property by observing contract balance.

        // Single assertion: the contract's balance has decreased by `amount` when call succeeded.
        // This holds for the reference for all inputs; the mutant (which sends to msg.sender)
        // will fail this assertion for cases where owner != receiver and amount > 0.
        if (ok) {
            assertTrue(address(c).balance == beforeContract - amount);
        } else {
            // If call reverted, still assert the contract balance is unchanged (reference meets this too).
            assertTrue(address(c).balance == beforeContract);
        }
    }
}

