pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: amount to send, recipient address, and the initial funding amount
    function testFuzz_property(uint256 amount, address receiver, uint256 fund) public {
        // Keep domains wide but sensible
        vm.assume(receiver != address(0)); // receiver must be a valid address
        // bound fund to a reasonable range so vm.deal can operate
        fund = bound(fund, 0, 1 ether);
        // amount must be within [0, fund]
        amount = bound(amount, 0, fund);

        // Fund the contract from the owner (setUp deployer is msg.sender at deployment)
        // Note: c's owner is the deployer (this test contract) so we act as this test contract
        vm.deal(address(this), fund);
        // Send funds into c so it has balance to forward
        (bool sent,) = address(c).call{value: fund}("");
        require(sent, "funding failed");

        // record balance before
        uint256 before = address(c).balance;

        // call sendTo as the owner (this contract)
        bool ok;
        try c.sendTo{value: 0}(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, the contract's balance must have decreased by exactly amount if call succeeded,
        // or remain the same if call reverted. This is a general invariant for the reference implementation.
        // Single assertion reading c via address(c).balance
        if (ok) {
            assertTrue(address(c).balance + amount == before);
        } else {
            assertTrue(address(c).balance == before);
        }
    }
}
